; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcmin (Amstrad CPC - minimal firmware (own screen and keys, firmware for discs and ROMs)), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 1		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)

ntc_start:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			di				; (KL ROM SELECT lets interrupts in again)
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld ix, ntc_go
			jp ntc_plat_irqon		; interrupt handler for normal mode
ntc_go:
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_scrinit		; mode 1, ROMs off, clear screen
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; Main.bas 6: total = 0
			dw kw_l_mov, llit_0, var_total

			; Main.bas 7: name = "NTC"
			dw kw_strcpy, var_name, str0

			; Main.bas 21: For i = 0 To (MAX - 1)
			dw kw_ztov, var_i
for1_t:

			; Main.bas 23: squares(i) = square(i)
			dw p_square_c, var_i
			dw kw_aset, arr_squares, var_i, var_square_square

			; Main.bas 24: Next
			dw kw_next1l_n, var_i, 9, for1_t
for1_e:

			; Main.bas 25: i = 0
			dw kw_ztov, var_i

			; Main.bas 26: While (i < MAX)
			dw wh2_c_go
wh2_t:

			; Main.bas 28: If ((i Mod 2) = 0) Then
			dw kw_modvl, var_i, 2, tmp0
			dw kw_cpeqvl, tmp0, 0
			dw kw_goto_iffalse_n, if3_1

			; Main.bas 30: total = (total + squares(i))
			dw kw_aget, arr_squares, var_i, tmp1
			dw kw_l_itol, tmp1, ltmp1
			dw kw_l_add, var_total, ltmp1, var_total

			; Main.bas 31: End If
if3_1:

			; Main.bas 32: i = i + 1
			dw kw_inc, var_i

			; Main.bas 33: Wend
wh2_c:
			dw kw_scpltvl, var_i, 10
			dw kw_goto_iftrue_n, wh2_t
wh2_e:

			; Main.bas 34: Print ("Hello from " & (LCase$(name)))
			dw kw_strlcase, stmp0, var_name
			dw kw_printzoscii
			dw glyph_48, glyph_65, glyph_6C, glyph_6C, glyph_6F, glyph_20, glyph_66, glyph_72
			dw glyph_6F, glyph_6D, glyph_20, 0		; "Hello from "
			dw kw_printstrvar, stmp0
			dw kw_printnl

			; Main.bas 35: Call report("even squares", total)
			dw kw_l_cstr, stmp1, var_total
			dw p_report_c, str1, stmp1

			; Main.bas 36: c.label = "count"
			dw kw_strcpy, var_counter_label, str2

			; Main.bas 37: For j = 10 To 1 Step -3
			dw kw_ltov, 10, var_j
for4_t:

			; Main.bas 39: Call c.add(j)
			dw p_counter_add_c, var_j

			; Main.bas 40: Print j; " ";
			dw kw_printint, var_j
			dw kw_printzoscii
			dw glyph_20, 0		; " "

			; Main.bas 41: Next
			dw kw_nextdnl_n, var_j, -3, 1, for4_t
for4_e:

			; Main.bas 42: Print
			dw kw_printnl

			; Main.bas 43: Print c.describe(); " in "; c.steps; " steps"
			dw p_counter_describe_c
			dw kw_printstrvar, var_counter_describe_describe
			dw p_counter_steps_get_c
			dw kw_printzoscii
			dw glyph_20, glyph_69, glyph_6E, glyph_20, 0		; " in "
			dw kw_printint, var_counter_steps_get_steps
			dw kw_printzoscii
			dw glyph_20, glyph_73, glyph_74, glyph_65, glyph_70, glyph_73, 1, 0		; " steps\n"
			dw kw_stop

; ============================================================
; function square (normal mode)
; ============================================================

p_square:

			; Main.bas 13: square = (n * n)
			dw kw_mulvv, var_square_n, var_square_n, var_square_square
			dw p_square_r

; ============================================================
; sub report (normal mode)
; ============================================================

p_report:

			; Main.bas 18: Print ((label & ": ") & value)
			dw kw_printstrvar, var_report_label
			dw kw_printzoscii
			dw glyph_3A, glyph_20, 0		; ": "
			dw kw_printstrvar, var_report_value
			dw kw_printnl
			dw p_report_r

; ============================================================
; sub add (normal mode)
; ============================================================

p_counter_add:

			; Counter.cls 10: Me.total = (Me.total + n)
			dw kw_l_itol, var_counter_add_n, ltmp1
			dw kw_l_add, var_counter_total, ltmp1, var_counter_total

			; Counter.cls 11: Call Me.p_bump()
			dw p_counter_p_bump_c
			dw p_counter_add_r

; ============================================================
; sub p_bump (normal mode)
; ============================================================

p_counter_p_bump:

			; Counter.cls 16: Me.p_steps = Me.p_steps + 1
			dw kw_inc, var_counter_p_steps
			dw p_counter_p_bump_r

; ============================================================
; propget steps (normal mode)
; ============================================================

p_counter_steps_get:

			; Counter.cls 21: steps = Me.p_steps
			dw kw_vtov, var_counter_p_steps, var_counter_steps_get_steps
			dw p_counter_steps_get_r

; ============================================================
; function describe (normal mode)
; ============================================================

p_counter_describe:

			; Counter.cls 26: describe = ((Me.label & "=") & Me.total)
			dw kw_strcpy, stmp0, var_counter_label
			dw kw_strcat, stmp0, str3
			dw kw_l_cstr, stmp1, var_counter_total
			dw kw_strcpy, var_counter_describe_describe, stmp0
			dw kw_strcat, var_counter_describe_describe, stmp1
			dw p_counter_describe_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

wh2_c_go:			ld sp, wh2_c
			jp ntc_xn

p_square_c:		; call square (normal)
			pop hl			; n
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_square_n), de
			ld hl, 0
			ld (var_square_square), hl
			ld (p_square_rs), sp
			ld sp, p_square
			jp ntc_xn
p_square_r:		; end of square
			ld sp, (p_square_rs)
			jp ntc_xn
p_report_c:		; call report (normal)
			pop hl			; label
			ld de, var_report_label
			ld b, 255
p_report_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_report_si0_e
			inc hl
			inc de
			djnz p_report_si0
			xor a
			ld (de), a
p_report_si0_e:
			pop hl			; value
			ld de, var_report_value
			ld b, 255
p_report_si1:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_report_si1_e
			inc hl
			inc de
			djnz p_report_si1
			xor a
			ld (de), a
p_report_si1_e:
			ld (p_report_rs), sp
			ld sp, p_report
			jp ntc_xn
p_report_r:		; end of report
			ld sp, (p_report_rs)
			jp ntc_xn
p_counter_add_c:		; call add (normal)
			pop hl			; n
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_counter_add_n), de
			ld (p_counter_add_rs), sp
			ld sp, p_counter_add
			jp ntc_xn
p_counter_add_r:		; end of add
			ld sp, (p_counter_add_rs)
			jp ntc_xn
p_counter_p_bump_c:		; call p_bump (normal)
			ld (p_counter_p_bump_rs), sp
			ld sp, p_counter_p_bump
			jp ntc_xn
p_counter_p_bump_r:		; end of p_bump
			ld sp, (p_counter_p_bump_rs)
			jp ntc_xn
p_counter_steps_get_c:		; call steps (normal)
			ld hl, 0
			ld (var_counter_steps_get_steps), hl
			ld (p_counter_steps_get_rs), sp
			ld sp, p_counter_steps_get
			jp ntc_xn
p_counter_steps_get_r:		; end of steps
			ld sp, (p_counter_steps_get_rs)
			jp ntc_xn
p_counter_describe_c:		; call describe (normal)
			xor a
			ld (var_counter_describe_describe), a
			ld (p_counter_describe_rs), sp
			ld sp, p_counter_describe
			jp ntc_xn
p_counter_describe_r:		; end of describe
			ld sp, (p_counter_describe_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_total:			dw 0, 0
			db 40			; capacity
var_name:			ds 41
var_i:			dw 0
var_square_square:			dw 0
			db 40			; capacity
var_counter_label:			ds 41
var_j:			dw 0
			db 255			; capacity
var_counter_describe_describe:			ds 256
var_counter_steps_get_steps:			dw 0
p_square_rs:			dw 0
var_square_n:			dw 0
p_report_rs:			dw 0
			db 255			; capacity
var_report_label:			ds 256
			db 255			; capacity
var_report_value:			ds 256
p_counter_add_rs:			dw 0
var_counter_add_n:			dw 0
var_counter_total:			dw 0, 0
p_counter_p_bump_rs:			dw 0
var_counter_p_steps:			dw 0
p_counter_steps_get_rs:			dw 0
p_counter_describe_rs:			dw 0
tmp0:			dw 0
tmp1:			dw 0
			db 255			; capacity
stmp0:			ds 256
			db 255			; capacity
stmp1:			ds 256
ltmp0:			dw 0, 0
ltmp1:			dw 0, 0

; numbers passed by address (read only)
llit_0:			dw 0, 0

; ============================================================
; ZOSCII glyphs - each points at its 8 byte bitmap in ntc_font
; ============================================================

glyph_20			equ ntc_font + 0		; " "
glyph_3A			equ ntc_font + 208		; ":"
glyph_48			equ ntc_font + 320		; "H"
glyph_65			equ ntc_font + 552		; "e"
glyph_66			equ ntc_font + 560		; "f"
glyph_69			equ ntc_font + 584		; "i"
glyph_6C			equ ntc_font + 608		; "l"
glyph_6D			equ ntc_font + 616		; "m"
glyph_6E			equ ntc_font + 624		; "n"
glyph_6F			equ ntc_font + 632		; "o"
glyph_70			equ ntc_font + 640		; "p"
glyph_72			equ ntc_font + 656		; "r"
glyph_73			equ ntc_font + 664		; "s"
glyph_74			equ ntc_font + 672		; "t"

; ============================================================
; Strings
; ============================================================

str0:			db "NTC", 0
str1:			db "even squares", 0
str2:			db "count", 0
str3:			db "=", 0

; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the ROM NTC CPCMIN (NTCMIN.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_goto_iffalse_n:	jp 11
kw_goto_iftrue_n:	jp 13
kw_next1l_n:	jp 31
kw_nextdnl_n:	jp 40
kw_ltov:		jp 47
kw_vtov:		jp 48
kw_ztov:		jp 49
kw_inc:		jp 51
kw_mulvv:	jp 60
kw_modvl:	jp 67
kw_scpltvl:	jp 80
kw_cpeqvl:	jp 96
kw_aget:		jp 111
kw_aset:		jp 112
kw_strcpy:	jp 122
kw_strcat:	jp 124
kw_printzoscii:	jp 129
kw_printstrvar:	jp 130
kw_printint:	jp 132
kw_printnl:	jp 139
kw_scrinit:	jp 147
kw_strlcase:	jp 182
kw_l_mov:	jp 207
kw_l_itol:	jp 208
kw_l_add:	jp 210
kw_l_cstr:	jp 236
kw_bssinit:	jp 291
ntc_plat_irqon:	jp 316
NTC_RJ_N	equ 30		; entries
ntc_csp	equ #8800		; ROM data
ntc_font	equ #948E		; ROM bss
ntc_nmode	equ #8807		; ROM data
ntc_v_free	equ #8984		; ROM data
ntc_v_romen	equ #898A		; ROM data
ntc_v_romold	equ #898C		; ROM data
ntc_v_stamp	equ #8988		; ROM data
ntc_v_start	equ #8986		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; the start: find the ROM in slots 0 - 31, have it patch the jump block. NC = ready;
; C = not there / too old (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, c				; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot; C: DE = a number it hasn't got
			jr c, ntc_rj_lacks
			ld hl, ntc_free
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, 0
			ld (ntc_v_stamp), hl
			ld a, 0
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld hl, ntc_rj_tlk
			or a
			sbc hl, de			; (DE: past the message shown)
			jr nz, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)
ntc_rj_num:		dw 0
ntc_rj_sig:		db "NTC", 1, "CPCMIN", 0	; the ROM's NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "ROM NTC CPCMIN (NTCMIN.ROM) not found", 0
ntc_rj_tlk:		db "ROM NTC CPCMIN too old: no routine #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0

ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bss		equ ntc_end
arr_squares		equ ntc_bss + 0		; 20 bytes
ntc_bss_size	equ 20
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
			SAVEAMSDOS "JSDEMO.BIN", ntc_start, ntc_end - ntc_start, ntc_start
